import{_ as t,a as o,b as n}from"./chunks/4ceb50ff1ca80ab5f262.Jzb2XgBc.js";import{_ as a}from"./chunks/ac945418977052fbacd6.CObdY42w.js";import{_ as i,o as r,c as s,a5 as l}from"./chunks/framework.DNkHA0lr.js";const b=JSON.parse('{"title":"Make Millions With Your Mind (Turn Your Knowledge Into A Business)","description":"","frontmatter":{"title":"Make Millions With Your Mind (Turn Your Knowledge Into A Business)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/make-millions-with-your-mind-turn-your-knowledge-into-a-business.md","filePath":"en/letters/make-millions-with-your-mind-turn-your-knowledge-into-a-business.md"}'),p={name:"en/letters/make-millions-with-your-mind-turn-your-knowledge-into-a-business.md"};function h(u,e,d,m,c,y){return r(),s("div",null,[...e[0]||(e[0]=[l('<h1 id="make-millions-with-your-mind-turn-your-knowledge-into-a-business" tabindex="-1">Make Millions With Your Mind (Turn Your Knowledge Into A Business) <a class="header-anchor" href="#make-millions-with-your-mind-turn-your-knowledge-into-a-business" aria-label="Permalink to &quot;Make Millions With Your Mind (Turn Your Knowledge Into A Business)&quot;">​</a></h1><p>Dan Koe · 2023-11-17 · <a href="https://thedankoe.com/letters/make-millions-with-your-mind-turn-your-knowledge-into-a-business/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/make-millions-with-your-mind-turn-your-knowledge-into-a-business">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/2DTZ6Kcdtmk?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>When I was young, I made a crucial observation.</p><p>I had to earn with my mind, not my time.</p><p>I made the distinction between labor workers and creative workers.</p><p>Labor workers would try to accomplish as much as their bodies could handle within a specific time frame.</p><p>Creative workers would focus on solving the problems that would lead to the most results, regardless of time spent.</p><p>Labor workers were locked into a salary and schedule that paid them a certain amount of money for their efforts.</p><p>Creative workers created their own salary and schedule that paid them according to the level of problem they solved.</p><p>There’s nothing wrong with labor work.</p><p>But understand that you are trading time for money.</p><p>And your time is limited.</p><p>Doctors can be paid a great salary, but they are paid the same whether they save someone’s life or tell them to take some aspirin.</p><p>A writer can be paid as much as they want depending on what they write, what their product is, and how far their writing spreads.</p><p>Writing is one example here as we will discuss how to monetize anything you wish later in this letter.</p><p>The difference between creative workers and labor workers is owning a business.</p><p>Business is about solving a series of creative problems until you create the income and lifestyle you desire.</p><p>As soon as you stop solving creative problems around product and reach, your income stagnates and you become a slave to the work you built yourself into.</p><h3 id="my-evolution-from-time-to-mind" tabindex="-1">My Evolution From Time To Mind <a class="header-anchor" href="#my-evolution-from-time-to-mind" aria-label="Permalink to &quot;My Evolution From Time To Mind&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p>When I first started in business, the logical option was to freelance with a valuable skill.</p><p>It seemed beginner-friendly and cost zero dollars to start.</p><p>With years of manual effort, the joy that came from building the business slowly fell as my responsibilities rose.</p><p>I could only take on a specific amount of clients.</p><p>I only had so much time in the day.</p><p>Unless I wanted to stay in a self-made 9-5, I had to get creative. I had to evolve.</p><p>Creativity is dependent on the expansion of your mind.</p><p>So, through education and exposing myself to the unknown, I registered new opportunities to solve my problem.</p><p>I began writing online to attract new clients.</p><p>This removed the time-suck of manually reaching out to potential clients with cold email, cold call, and and cold messages.</p><p>I built a digital product that could sell while I sleep.</p><p>This removed my absolute dependence on client work to survive.</p><p>I pivoted my freelance offer into a consulting offer.</p><p>This cut my client work times in half. I could charge more and do less because I was helping someone rather than doing it for them.</p><p>During this time, I made a discovery that changed the direction of my life:</p><p>If I could gain one reader, I could gain one million.</p><p>And if I could gain one buyer, I could gain one thousand.</p><p>2.8 million readers and 20,000 buyers later, my discoveries held true.</p><p>Now, my creative problem-solving has evolved beyond a one-person business.</p><p>Now, I am focused on building <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a>, delegating work without reducing the quality delivered, and not overworking myself.</p><p>One lesson before we begin:</p><p>You can’t eradicate manual labor from your life altogether.</p><p>It is a slow and painful evolution, and sometimes you regress.</p><p>Now that I’ve taken on the responsibility of starting a larger company, my manual work has increased substantially, but I trust that I can lower it quickly with my prior experience.</p><h3 id="what-we-will-discuss" tabindex="-1">What we will discuss: <a class="header-anchor" href="#what-we-will-discuss" aria-label="Permalink to &quot;What we will discuss:&quot;">​</a></h3><ul><li>The macronutrients of business</li><li>Progressive overload of skill</li><li>Time under attention</li><li>How to reinvent yourself</li><li>Documenting your mind on the internet</li><li>How to create a brand, content, product, and promotions that make you money</li></ul><p>One other thing before we start – we have opened up more spots for VIP and Mastermind. If you are a founder, creator, writer, or marketer who wants to work with us directly on your social media brand, content, and product… <a href="https://intake.kortex.co/" target="_blank" rel="noreferrer">apply here</a>.</p><p>This letter is long, but worth it.</p><h2 id="bodybuilding-businessbuilding" tabindex="-1">Bodybuilding &amp; Businessbuilding <a class="header-anchor" href="#bodybuilding-businessbuilding" aria-label="Permalink to &quot;Bodybuilding &amp; Businessbuilding&quot;">​</a></h2><p>When you deconstruct the mind and body, you can map patterns that deepen your understanding across most domains of life.</p><p>We will connect these patterns to the financial domain by starting a business.</p><p>We can think of the mind as your mental body as we talked about in <a href="/letters/mental-aesthetics-how-to-build-a-beautiful-mind">Mental Aesthetics</a>.</p><p>We can also think of your business as the body or character you display externally.</p><p>A business is just that, a vessel for value exchange.</p><p><em>Personal growth is self-development, business growth is other-development.</em></p><p>In nutrition, there are 4 macronutrients:</p><ul><li>Fat</li><li>Carbs</li><li>Protein</li><li>Alcohol</li></ul><p>In business, there are 4 pillars that determine your success:</p><ul><li>Brand</li><li>Content</li><li>Product</li><li>Promotions</li></ul><p>In nutrition, there are a plethora of micronutrients that maintain bodily functions.</p><p>In business, there are skills, interests, experience, knowledge, creativity, and personality that determine the potency of your efforts.</p><p>Your job is to fuel your business with the proper creative nutrition to succeed.</p><p>You can opt for the business keto diet and take away content as carbs.</p><p>Many people go the direct response marketing route and only use ads to fuel their business, but the benefits of content make it an unreasonable approach (especially for beginners without money to invest in making mistakes to learn advertising… <a href="/letters/my-story-the-untold-truth-of-dan-koe">I learned this the hard way</a>).</p><p>By having a daily content writing habit:</p><ul><li>You can validate high-performing ideas as content to use in your ads or promotions.</li><li>You get to keep the audience you acquire. You aren’t always burning through money to acquire new customers.</li><li>You create customers over time by writing content for all levels of awareness.</li></ul><p>You can spend hundreds of thousands of dollars a year on ads.</p><p>Or you can build a 100,000 follower audience over a year and get the same amount of impressions.</p><p>Or you can do both, your call.</p><h3 id="progressive-overload-of-skill-challenge" tabindex="-1">Progressive Overload Of Skill &amp; Challenge <a class="header-anchor" href="#progressive-overload-of-skill-challenge" aria-label="Permalink to &quot;Progressive Overload Of Skill &amp; Challenge&quot;">​</a></h3><p><img src="'+a+'" alt=""></p><p>When you are starting out, it is unwise to take on too much as a one-person business.</p><p>You must become the marketing, sales, operations, and media department.</p><p>To create a brand, content, product, and promotions, you will need to learn at least the fundamentals of:</p><ul><li>Marketing &amp; sales</li><li>Graphic design</li><li>Web design</li><li>Copywriting</li><li>Content writing</li><li>Email marketing</li><li>Social media</li></ul><p>This is a blessing and a curse.</p><p>If you’ve never learned any modern skills, this will take a while.</p><p>You will get overwhelmed and anxious at the thought of a future you don’t have the skill to create clarity with.</p><p>But social media is the perfect vessel to build as you learn.</p><p>In bodybuilding, you progressively overload the muscle by adding weight to the bar over time.</p><p>If you ego-lift and put on too much weight, you won’t be able to lift it, and you’ll probably look like an idiot.</p><p>Start small and build your skill stack with time.</p><p>Do not start learning until you start building.</p><p>Buy courses, books, and search for content that teaches how to do all of this well as you are building.</p><p>Create one project.<br> Set one goal.<br> Learn one skill.<br> Get good at it so you have mental energy for the next.<br> Repeat.</p><p><strong>Build your profile.</strong> Study social media and graphic design (for your banner and profile picture).</p><p><strong>Start writing content</strong>. Study copywriting, content writing, marketing, and post structures.</p><p><strong>Ideate a product.</strong> Study marketing, sales, and offer creation.</p><p><strong>Learn to promote.</strong> Study email marketing, promotions, and copywriting.</p><p>With all of this, don’t get complacent.</p><p>If you don’t seek a higher challenge after you stop seeing good results from the first, you will get bored.</p><p>Boredom leads to thoughts of quitting because you feel like there is something better you could be doing with your time.</p><p>In the gym, a great thing to do is observe what others are doing to correct your form. You can also watch videos of people online.</p><p>Emulate what others are doing in the creator space.</p><p>Pull inspiration from creators’ bios, content, and marketing.</p><p>But – and this is a <em>big</em> but – realize that people more advanced than you are at a different level. What they are doing may not be what they did when they were starting out.</p><p>This is a long process of experimentation.</p><h3 id="time-under-attention" tabindex="-1">Time Under Attention <a class="header-anchor" href="#time-under-attention" aria-label="Permalink to &quot;Time Under Attention&quot;">​</a></h3><p><img src="'+o+'" alt=""></p><p>In weight training, there is a concept known as <em>time under tension</em>.</p><p>Some argue it is the main driver of muscle growth (paired with progressive overload).</p><p>I want to make the same argument for business, but as <em>time under <strong>attention</strong></em>.</p><p>This is arguably the most important thing to pay attention to when building an audience with your writing and content.</p><p>Attention is the currency of the 3rd millennium.</p><p>The more people pay attention to you, the more power you have.</p><p>Authors, podcasters, and YouTubers often have the most loyal audiences.</p><p>Why? Because information creates identity.</p><p>The more attention you hold, the more information you deliver.</p><p>You program the minds of your audience in a way that is conducive to actually changing their life.</p><p>You can write short posts for social media all day long, but someone who has held more attention will always outperform you.</p><p>James Clear will get more engagement and reach because:</p><ul><li>People have adopted his worldview.</li><li>People quote him in their content, newsletters, and podcasts.</li><li>Any time someone else posts a related idea to Clear, the authority is given to Clear because he comes to mind while reading <em>your</em> content. Clear is still holding their attention while they read others’ content.</li></ul><p>This does not mean that short-form content like X, Instagram, or LinkedIn are useless. Quite the opposite. They have their own benefits and use cases.</p><p>Don’t think in black and white here. Think holistically.</p><p>I see short-form platforms as a way to attract a broad audience quicker to fuel your long-form platforms that are arguably more difficult to grow.</p><p>I almost always recommend starting with short-form to build an audience, build a network, and validate high-performing ideas that you can then turn into long-form videos, newsletters, or combine all of them into a book.</p><p>And, the longer you do it, the more attention you hold. Quitting after 1-6 months is stupid.</p><p>1% of 50 years is 6 months.</p><p>If this is the work you see yourself doing for your entire life, don’t quit during the tutorial phase.</p><p>If I create 365 posts a year (on all platforms) and those posts hold attention for 30 seconds, that’s 3 hours of attention held – per reader – on each platform over a year.</p><p>If I create 1 long-form post a week (for a newsletter, YouTube, and podcast all being the same) and these posts hold 20 minutes of attention, that’s 52 hours of attention held per reader for all platforms.</p><p>I’ll let you come to the conclusion of why I wrote a book that may be purchased by millions.</p><p>So, it’s important that you treat short-form platforms for what they are:</p><p>A way to build a broad audience faster, validate ideas, and funnel people into various products and long-form content.</p><p>For writers, I always recommend using X and a newsletter.</p><p>One short-form and one long-form platform to start.</p><p>Then, when you’ve spent enough time actually seeing growth, you can repurpose all of your best short and long-form content for different platforms. This is what I teach in <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>.</p><h2 id="turn-your-self-into-a-business-mental-monetization" tabindex="-1">Turn Your Self Into A Business (Mental Monetization) <a class="header-anchor" href="#turn-your-self-into-a-business-mental-monetization" aria-label="Permalink to &quot;Turn Your Self Into A Business (Mental Monetization)&quot;">​</a></h2><p><img src="'+n+'" alt=""></p><p>Your self, or identity, is your mental body.</p><p>The “self” is a web of concepts, beliefs, ideas, experiences, and perceptions that allow you to navigate the world.</p><p>The information you learn and use since birth is what shapes the self.</p><p>Your identity shapes your perspective, and your perspective is the most important thing you can understand and expand.</p><p>Your perspective is your reality.</p><p>A perspective is a frame composed of goals, problems, and skill to overcome those problems to achieve those goals.</p><p>It is also composed of beliefs, knowledge, and experiences that either limit or aid in the achievement of goals, solving of problems, and understanding of knowledge.</p><p>When we aren’t conscious of the goals or problems that compose our perspective, we are not choosing how we act. The goals were assigned to us.</p><p>If we don’t have the skill to overcome problems to achieve goals, we get anxious, overwhelmed, and negative to the point of lashing out.</p><p>When you don’t seek to understand the goal of someone else in life, social media, politics, religion, or the rest – it is easy for us to misinterpret their situation and think they are stupid for doing what they do.</p><p>In reality, we lack perspective.</p><p>We can’t open our minds to see that we are not the only perspective.</p><p>The goals and problems that compose your perspective determine what information you perceive as important.</p><p>Given time, the information you consume either reinforces who you are or changes who you are by expanding your perspective to contain better problems and meaningful goals.</p><p>From those meaningful goals, you can acquire a unique combination of skills to achieve them.</p><p><strong>Person A has an unconscious goal that was assigned to them by society.</strong></p><p>They were made to believe that getting a job as a doctor was their only path in life.</p><p>So, whether they know it or not, all of the information, books, podcasts, social media content, and conversations will be interpreted to acquire information that helps them achieve their goal.</p><p>Their skillset will form from that information as they attempt to achieve the goal.</p><p>There are more goals and problems influencing interpretation here – like watching memes on their phone all day because they don’t have a stronger goal that requires them to self-educate to achieve it.</p><p><strong>Person B has a conscious goal that they chose for themself based on a problem they became aware of.</strong></p><p>This sets them up for success in more ways than just achieving their goal.</p><p>First, it prevents them from being a mindless product of the social matrix (the groundless loop of webbed information passed down from the government, schools, and parents just so they can teach their children the same).</p><p>Second, the path of changing who they are, creating a unique path in life, and achieving goals that solve burning problems sets them up for a life of meaning, money, and mastery.</p><h3 id="documenting-your-mind-on-the-internet-and-getting-paid-to-do-so" tabindex="-1">Documenting Your Mind On The Internet (And Getting Paid To Do So) <a class="header-anchor" href="#documenting-your-mind-on-the-internet-and-getting-paid-to-do-so" aria-label="Permalink to &quot;Documenting Your Mind On The Internet (And Getting Paid To Do So)&quot;">​</a></h3><p>Now we understand a very brief description of the human behavior feedback loop.</p><p>Identity influences perspective influences perception of situations influences choices influences identity and loops back around to infinity.</p><p>To turn your mind into a business, your job is to change your behavior for the better so you can change others.</p><p><strong>1) Brand Is Your Online Character Or Identity</strong></p><p>The front end of a business is a brand. This is what they display online to attract the right people and illustrate their digital identity.</p><p>Since we are turning <em>your</em> self into the business, your job is to attract the people you can help the most:</p><p>People that are like you.</p><p>The people who share the same goals and problems as your past or present self but don’t have the skill to achieve and overcome them.</p><p>You already have the knowledge, experience, and skills to pass down to those who are one step behind you. That’s all you need to start a business.</p><p>So, your job on your website, social media profiles, and anywhere your brand is displayed is to:</p><ul><li>Imply a meaningful goal you help people achieve.</li><li>Imply a burning problem you can help them solve.</li><li>Imply the interests or skills that you teach to bridge the gap between problem and goal.</li></ul><p>This creates your digital reality.</p><p>It creates the frame that you and your customers share so you can exchange knowledge and skill.</p><p>This does not have to be explicitly said in your branding.</p><p>It must be implied in your designs, writing, and video.</p><p>Your brand is created with time under attention as people learn more about you through your content and products.</p><p>My brand slogan is: <em>Work less. Earn more. Enjoy life.</em></p><p>My bio was occasionally: <em>I write about human potential, writing, and mental mastery so you can do what you want.</em></p><p>I don’t recommend copying these as they probably won’t work for you. I have more time under attention than you and have the freedom to not be as explicit. This will require more study of my other letters like <a href="/letters/value-creation-the-skill-that-built-my-one-person-business">Value Creation</a> or <a href="/letters/the-most-important-skill-of-the-21st-century-only-1-use-it">The Greatest Skill Of The 21st Century</a>.</p><p><strong>2) Content Is Your Mindset &amp; Skillset</strong></p><p>Content becomes a necessity when you realize its power.</p><p>Marketers know the power of traffic, a list of interested customers, and the power of long-form writing or video – but many of them come around to the content game late (like myself).</p><p>They don’t realize that the long webinar that made you millions can just be a video on YouTube that gets hundreds of thousands of views (once you get the hang of the social media game).</p><p>I understand a webinar funnel, or similar, can be more strategic, but it doesn’t rule out the other benefits of writing content:</p><ul><li><strong>You enhance your thinking.</strong> Your ideas become clear with time and it ripples into the rest of your life. You can’t have a great idea if you don’t write a good idea first. Your first content won’t be that good, that’s okay.</li><li><strong>It’s free most of the time.</strong> You can grow organically, or you can move your ad spend to paid growth by connecting with and having big players share your posts (don’t listen to anyone that tells you this doesn’t work, they don’t understand it. It doesn’t work for them because their brand and content and strategy suck).</li><li><strong>You create customers.</strong> Unlike ads, you keep your audience and can remarket to them at any time. As you create educational content, people <em>become</em> customers because your information shapes who they are.</li><li><strong>You validate and test ideas fast.</strong> I can send out a tweet, and if it does better than usual, I can turn that into a sales page headline, YouTube title, or entire product that I know will sell.</li></ul><p>Here is how I help <a href="https://intake.kortex.co/" target="_blank" rel="noreferrer">people I work with</a> to build their brand by dissecting their minds to turn into content.</p><p>First, answer these questions (write the answers down so you can write content with the answers):</p><ol><li>What are 5-10 beliefs that are seen as “extreme” or “crazy” to other people but are normal to you? (This is what differentiates you and leads to the most growth.) I.E. I believe entrepreneurship is for everyone and have reasoning from psychology, mechanics, history, and philosophy to back that.</li><li>What are 5-10 interests or skills that help you create the lifestyle you live and help your followers achieve?</li><li>Why are those interests or skills important? What do they help people avoid or gain in life?</li><li>What foundational knowledge do people need to understand about those skills or interests? (This keeps you from being too advanced or high level so you actually resonate with people.</li></ol><p>Now, pair these with the <a href="/letters/the-most-important-skill-of-the-21st-century-only-1-use-it">10 Koemmandments of Engagement</a> and try turning everything you listed into content. It also helps to understand the principles of Value Creation which I linked above.</p><p>During this process, write so a 5th grader can understand you.</p><p>That is a huge problem I see in the space. People overcomplicate their message with niche wording that doesn’t attract people to <em>become</em> interested in your interests.</p><p>You aren’t attracting people who are already interested. You are <em>making</em> them interested through persuasion.</p><p>Lastly, here are a few traps people fall into:</p><p><em>Trap 1 – They focus way too much on promotions or making sure they only talk about their product.</em></p><p>Talk about your beliefs, opinions, and educate people on the information necessary to become above average in your interests and skills 80% of the time. Promote sparingly. It’s like cashing in goodwill with your audience.</p><p><em>Trap 2 – They don’t understand the importance of structure VS content.</em></p><p>This goes far beyond writing content for business. It is a metaphysical principle.</p><p>For now, take your <em>ideas</em> and use high-performing structures and frameworks as training wheels until you actually develop your writing ability. Look at quotes, newsletter structures, post structures, and the rest and try plugging your ideas into them.</p><p><em>Trap 3 – They don’t research or use high-performing angles.</em></p><p>Any idea can go viral. But only when it is positioned in an attention-grabbing way that entertains, educates, or inspires.</p><p>You are a dopamine dealer.</p><p>You raise dopamine levels in your readers’ brains by teaching them something new, giving a new point of view, entertaining them, or showing them they are capable of more in life.</p><p>Study your favorite accounts’ most popular X posts, Instagram posts, YouTube videos, and start programming your mind to think in high-performing headlines.</p><p>The lesson of content:</p><p><em>Good content occurs when you attempt to inject your mindset and skillset into your readers over the course of 6-12 months, not in one post.</em></p><p><strong>3) Product Is How You Achieved A Meaningful Goal</strong></p><p>When you are the niche, people follow you because they want to achieve the lifestyle you have. They want to do what you do.</p><p>You are already educating them on how to do it with your content.</p><p>The difference between content and product is convenience, clarity, and a replicable system that gets results.</p><p><em>What is the most meaningful goal you achieved in your life?</em></p><p>(My example: I earn a living writing about my interests.)</p><p>(Potential example: I got a six-pack without doing cardio.)</p><p>(Another example: I unlocked extreme focus to build my side business.)</p><p><em>What steps do people need to take to get there?</em></p><p>(My example: Write, build a readership, persuade, sell.)</p><p>(Potential example: Minimalist training and intermittent fasting.)</p><p><em>What do people need to learn to take those steps?</em></p><p>(My example: Social media, copywriting, content.)</p><p>(Potential example: The principles of training and nutrition.)</p><p><em>What can those people practice and implement in their day to get there?</em></p><p>(My example: the 2 hour content ecosystem.)</p><p>(Potential example: the executive training system for busy people.)</p><p>(I’m giving these systems fancy names because it is known as a “unique mechanism” in marketing. It is novel. Novelty catches attention and makes people think, “This may be the thing that finally solves my problem!”)</p><p>Boom, that’s the outline of your product.</p><p>Please note that those are all brief mediocre examples. Get more specific.</p><p>A “meaningful goal” that you help people achieve is determined by solving a burning problem within human nature in the eternal markets: health, wealth, relationships, and happiness.</p><p>If you haven’t already achieved a meaningful goal in a unique way, I will help you in another letter about mastering new skills fast.</p><p>Until then:</p><ul><li>Set a goal in one domain of your life.</li><li>Drown yourself in knowledge and education around it.</li><li>Document that knowledge as content (teaching is how you learn and identify what you don’t know so that you can learn efficiently).</li><li>Crucial: experiment with different techniques (like training programs, diets, ways to make money, etc).</li><li>Identify the fundamentals, truths, and principles between the different techniques.</li><li>Achieve the goal by creating your own way of getting there.</li></ul><p>Then, distribute that as a digital product that sells while you sleep with obscenely high-profit margins.</p><p>From there, you have the resources (readership and income) to build whatever other business your heart desires.</p><p><strong>4) Promotions Are Why You Achieved The Goal</strong></p><p>People don’t care about features, they care about benefits.</p><p>Assume that everyone is selfish, because they are, even if that selfishness comes from feeling good about themselves by being selfless.</p><p>Marketing is about creating the most powerful “why.”</p><p>A “why” implies a transformation.</p><p>Transformations are what people want.</p><p>Like how physique transformation journeys always get a lot of views on YouTube.</p><p>Or how life transformations get you emotional and invested in the person.</p><p>A transformation is a story, and that’s what our minds’ are wired to be attracted to, trust, and connected to.</p><p>So, you need to do 1 of 2 things:</p><ol><li>Tell people why the product will change their life.</li><li>Tell people why it changed your life (because they will read it as if they were changing there’s).</li></ol><p>I’ve been a marketer for almost 6 years now.</p><p>Here’s all you need to know to actually make some money.</p><p>A story or transformation is composed of 3 things:</p><ol><li>A burning problem.</li><li>A desirable outcome.</li><li>A clear solution.</li></ol><p>That’s your entire marketing campaign.</p><p>You will have to test each one until you strike gold with the right positioning, but then you are set for a while.</p><p>Those 3 components will be used whenever you ask someone to buy your product in your emails, landing page, IG story, YouTube promotion, or the rest.</p><p>Long-form promotions are like a full sales page, you have to fill up the page by guiding people through that structure (go and read the introduction of this letter).</p><p>Short-form promotions are like a call to action inside an email like:</p><p>If you’ve tried the “latest and greatest” business models without any success (and are considering accepting your fate at a day job), it’s because you are falling for tactics.</p><p>In <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>, I teach the principles of building a purposeful business.</p><p>Brand, content, product, and promotions so you can talk about your interests and earn a creative income.</p><p>Now, when writing promotions, you have to know what part of your audience you are talking to. How long have they been reading your content and do they understand your philosophy?</p><p>I see this mistake often.</p><p>People have very high-level language (like manifesting a life of alignment to be a peaceful being) and their audience couldn’t care less.</p><p>If you haven’t defined “alignment” and “manifesting” to your beginner-level audience, then don’t write this way.</p><p>Be straightforward. Be simple. Be impactful.</p><p>Give people what they want.</p><p>Don’t give people what you think they want.</p><p>That’s it for this one, it’s already way too long.</p><p>I hope you enjoyed it.</p><p>Dan</p>',259)])])}const k=i(p,[["render",h]]);export{b as __pageData,k as default};
